C0022.falsifier_code:
import bench.dm._memory as mod

def falsify():
    mem = mod.ImmuneMemory()
    before_ids = list(mem._experiment_ids)
    before_count = mem._experiment_count

    try:
        mem.record_experiment(exp_id="e1", flaw_counts={"not_an_int": (1, 2)})
    except mod.MemoryIntegrityError:
        pass
    except (TypeError, ValueError) as exc:
        assert list(mem._experiment_ids) == before_ids
        assert mem._experiment_count == before_count
        raise AssertionError(
            "FALSIFIED: record_experiment raised a raw "
            f"{type(exc).__name__} ({exc}) instead of MemoryIntegrityError "
            "when the flaw-class key itself failed int() conversion"
        )
    else:
        raise AssertionError("expected an exception, got none")

    mem2 = mod.ImmuneMemory()
    try:
        mem2.record_experiment(exp_id="e2", flaw_counts={None: (1, 2)})
    except mod.MemoryIntegrityError:
        pass
    except (TypeError, ValueError) as exc:
        raise AssertionError(
            "FALSIFIED: record_experiment raised a raw "
            f"{type(exc).__name__} ({exc}) instead of MemoryIntegrityError "
            "when the flaw-class key (None) failed int() conversion"
        )
    else:
        raise AssertionError("expected an exception, got none")

    print("no defect detected: both bad keys raised MemoryIntegrityError")

if __name__ == "__main__":
    falsify()

